import{_ as e,o as i,c as n,ai as s}from"./chunks/framework.CaiDwmc7.js";const k=JSON.parse('{"title":"Conventional Commits 1.0.0","description":"","frontmatter":{},"headers":[],"relativePath":"conventional_commit.md","filePath":"conventional_commit.md"}'),t={name:"conventional_commit.md"};function o(l,a,d,r,c,p){return i(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="conventional-commits-1-0-0" tabindex="-1">Conventional Commits 1.0.0 <a class="header-anchor" href="#conventional-commits-1-0-0" aria-label="Permalink to “Conventional Commits 1.0.0”">​</a></h1><h2 id="ringkasan" tabindex="-1">Ringkasan <a class="header-anchor" href="#ringkasan" aria-label="Permalink to “Ringkasan”">​</a></h2><p>Conventional Commits adalah konvensi ringan untuk menulis pesan commit. Tujuannya agar riwayat commit lebih jelas, konsisten, dan mudah dipakai oleh alat otomatis seperti generator changelog atau otomatisasi versi.</p><p>Konvensi ini selaras dengan SemVer karena membedakan commit fitur baru, perbaikan bug, dan perubahan yang bersifat breaking.</p><p>Format commit:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;type&gt;[optional scope]: &lt;description&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[optional body]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[optional footer(s)]</span></span></code></pre></div><p>Elemen struktural utama:</p><ul><li><code>fix</code>: commit ini memperbaiki bug (setara <code>PATCH</code> pada SemVer).</li><li><code>feat</code>: commit ini menambahkan fitur baru (setara <code>MINOR</code> pada SemVer).</li><li><code>BREAKING CHANGE</code>: perubahan yang memutus kompatibilitas API (setara <code>MAJOR</code> pada SemVer). Bisa ditulis di footer atau ditandai dengan <code>!</code> pada prefix.</li><li>Tipe selain <code>fix</code> dan <code>feat</code> tetap boleh digunakan, misalnya <code>build</code>, <code>chore</code>, <code>ci</code>, <code>docs</code>, <code>style</code>, <code>refactor</code>, <code>perf</code>, <code>test</code>, dan lainnya.</li><li>Footer selain <code>BREAKING CHANGE</code> juga boleh digunakan mengikuti pola mirip <code>git trailer</code>.</li></ul><p>Tipe tambahan tidak diwajibkan oleh spesifikasi dan tidak otomatis memengaruhi SemVer, kecuali jika mengandung breaking change.</p><p><code>scope</code> bersifat opsional dan dipakai untuk konteks area kode, misalnya:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat(parser): tambah kemampuan parse array</span></span></code></pre></div><h2 id="contoh" tabindex="-1">Contoh <a class="header-anchor" href="#contoh" aria-label="Permalink to “Contoh”">​</a></h2><h3 id="_1-commit-dengan-deskripsi-dan-footer-breaking-change" tabindex="-1">1) Commit dengan deskripsi dan footer breaking change <a class="header-anchor" href="#_1-commit-dengan-deskripsi-dan-footer-breaking-change" aria-label="Permalink to “1) Commit dengan deskripsi dan footer breaking change”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat: izinkan objek config mewarisi config lain</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BREAKING CHANGE: key \`extends\` sekarang dipakai untuk mewarisi file config lain</span></span></code></pre></div><h3 id="_2-commit-dengan-untuk-menandai-breaking-change" tabindex="-1">2) Commit dengan <code>!</code> untuk menandai breaking change <a class="header-anchor" href="#_2-commit-dengan-untuk-menandai-breaking-change" aria-label="Permalink to “2) Commit dengan ! untuk menandai breaking change”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat!: kirim email ke pelanggan saat produk dikirim</span></span></code></pre></div><h3 id="_3-commit-dengan-scope-dan" tabindex="-1">3) Commit dengan scope dan <code>!</code> <a class="header-anchor" href="#_3-commit-dengan-scope-dan" aria-label="Permalink to “3) Commit dengan scope dan !”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat(api)!: kirim email ke pelanggan saat produk dikirim</span></span></code></pre></div><h3 id="_4-commit-dengan-dan-footer-breaking-change" tabindex="-1">4) Commit dengan <code>!</code> dan footer <code>BREAKING CHANGE</code> <a class="header-anchor" href="#_4-commit-dengan-dan-footer-breaking-change" aria-label="Permalink to “4) Commit dengan ! dan footer BREAKING CHANGE”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat!: hentikan dukungan Node 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BREAKING CHANGE: sekarang memakai fitur JavaScript yang tidak tersedia di Node 6</span></span></code></pre></div><h3 id="_5-commit-tanpa-body" tabindex="-1">5) Commit tanpa body <a class="header-anchor" href="#_5-commit-tanpa-body" aria-label="Permalink to “5) Commit tanpa body”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docs: perbaiki ejaan pada CHANGELOG</span></span></code></pre></div><h3 id="_6-commit-dengan-scope" tabindex="-1">6) Commit dengan scope <a class="header-anchor" href="#_6-commit-dengan-scope" aria-label="Permalink to “6) Commit dengan scope”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat(lang): tambah bahasa Polandia</span></span></code></pre></div><h3 id="_7-commit-dengan-body-multi-paragraf-dan-banyak-footer" tabindex="-1">7) Commit dengan body multi-paragraf dan banyak footer <a class="header-anchor" href="#_7-commit-dengan-body-multi-paragraf-dan-banyak-footer" aria-label="Permalink to “7) Commit dengan body multi-paragraf dan banyak footer”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fix: cegah race condition pada request</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tambahkan request id dan referensi ke request terbaru.</span></span>
<span class="line"><span>Abaikan response yang bukan berasal dari request terbaru.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hapus timeout lama yang sebelumnya dipakai untuk mitigasi race condition</span></span>
<span class="line"><span>karena sekarang sudah tidak diperlukan.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reviewed-by: Z</span></span>
<span class="line"><span>Refs: #123</span></span></code></pre></div><h2 id="spesifikasi" tabindex="-1">Spesifikasi <a class="header-anchor" href="#spesifikasi" aria-label="Permalink to “Spesifikasi”">​</a></h2><p>Kata kunci RFC 2119 seperti MUST, SHOULD, MAY, dan lainnya berlaku pada bagian ini.</p><ul><li>Commit <strong>harus</strong> diawali <code>type</code>, diikuti <code>scope</code> opsional, <code>!</code> opsional, lalu <code>:</code> dan spasi.</li><li><code>feat</code> <strong>harus</strong> dipakai untuk fitur baru.</li><li><code>fix</code> <strong>harus</strong> dipakai untuk perbaikan bug.</li><li><code>scope</code> <strong>boleh</strong> ditambahkan setelah type dan harus berupa kata benda dalam tanda kurung, misalnya <code>fix(parser):</code>.</li><li><code>description</code> <strong>harus</strong> langsung setelah <code>:</code> dan spasi, berisi ringkasan singkat perubahan.</li><li><code>body</code> <strong>boleh</strong> ditambahkan satu baris kosong setelah deskripsi.</li><li><code>body</code> bersifat bebas dan boleh terdiri dari banyak paragraf.</li><li>Satu atau lebih <code>footer</code> <strong>boleh</strong> ditambahkan satu baris kosong setelah body.</li><li>Setiap footer terdiri dari token, pemisah (<code>:&lt;space&gt;</code> atau <code>&lt;space&gt;#</code>), dan nilai string.</li><li>Token footer harus menggunakan <code>-</code> untuk mengganti spasi (mis. <code>Acked-by</code>), kecuali <code>BREAKING CHANGE</code>.</li><li>Nilai footer boleh berisi spasi dan baris baru.</li><li>Breaking change harus ditandai di prefix (<code>!</code>) atau footer.</li><li>Jika memakai footer, formatnya harus: <code>BREAKING CHANGE: &lt;deskripsi&gt;</code>.</li><li>Jika memakai <code>!</code>, footer <code>BREAKING CHANGE</code> boleh dihilangkan.</li><li>Tipe selain <code>feat</code> dan <code>fix</code> tetap boleh digunakan.</li><li>Implementasi parser tidak boleh menganggap unit informasi sebagai case-sensitive, kecuali token <code>BREAKING CHANGE</code> yang harus uppercase.</li><li><code>BREAKING-CHANGE</code> dianggap sinonim dengan <code>BREAKING CHANGE</code> saat dipakai sebagai token footer.</li></ul><h2 id="kenapa-menggunakan-conventional-commits" tabindex="-1">Kenapa Menggunakan Conventional Commits? <a class="header-anchor" href="#kenapa-menggunakan-conventional-commits" aria-label="Permalink to “Kenapa Menggunakan Conventional Commits?”">​</a></h2><ul><li>Membuat changelog otomatis.</li><li>Menentukan kenaikan versi SemVer secara otomatis.</li><li>Mengkomunikasikan sifat perubahan ke tim dan stakeholder.</li><li>Memicu proses build/publish.</li><li>Memudahkan kontribusi karena histori commit lebih terstruktur.</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><h3 id="bagaimana-menulis-commit-saat-proyek-masih-fase-awal" tabindex="-1">Bagaimana menulis commit saat proyek masih fase awal? <a class="header-anchor" href="#bagaimana-menulis-commit-saat-proyek-masih-fase-awal" aria-label="Permalink to “Bagaimana menulis commit saat proyek masih fase awal?”">​</a></h3><p>Tulis seolah produk sudah dirilis. Biasanya sudah ada pengguna (minimal rekan tim) yang perlu tahu apa yang diperbaiki, ditambah, atau diubah secara breaking.</p><h3 id="type-commit-sebaiknya-huruf-besar-atau-kecil" tabindex="-1">Type commit sebaiknya huruf besar atau kecil? <a class="header-anchor" href="#type-commit-sebaiknya-huruf-besar-atau-kecil" aria-label="Permalink to “Type commit sebaiknya huruf besar atau kecil?”">​</a></h3><p>Bebas, tetapi sebaiknya konsisten. Praktik umum: huruf kecil.</p><h3 id="bagaimana-jika-satu-commit-cocok-ke-lebih-dari-satu-type" tabindex="-1">Bagaimana jika satu commit cocok ke lebih dari satu type? <a class="header-anchor" href="#bagaimana-jika-satu-commit-cocok-ke-lebih-dari-satu-type" aria-label="Permalink to “Bagaimana jika satu commit cocok ke lebih dari satu type?”">​</a></h3><p>Pisahkan menjadi beberapa commit jika memungkinkan. Manfaat utama Conventional Commits adalah mendorong commit yang lebih rapi dan terorganisir.</p><h3 id="apakah-ini-menghambat-pengembangan-cepat" tabindex="-1">Apakah ini menghambat pengembangan cepat? <a class="header-anchor" href="#apakah-ini-menghambat-pengembangan-cepat" aria-label="Permalink to “Apakah ini menghambat pengembangan cepat?”">​</a></h3><p>Tidak. Konvensi ini mengurangi kekacauan, sehingga tim bisa bergerak cepat secara berkelanjutan.</p><h3 id="apakah-developer-jadi-terlalu-terbatas-pada-type-yang-ada" tabindex="-1">Apakah developer jadi terlalu terbatas pada type yang ada? <a class="header-anchor" href="#apakah-developer-jadi-terlalu-terbatas-pada-type-yang-ada" aria-label="Permalink to “Apakah developer jadi terlalu terbatas pada type yang ada?”">​</a></h3><p>Tidak. Spesifikasi ini fleksibel; tim bisa menambah type sesuai kebutuhan.</p><h3 id="hubungannya-dengan-semver-bagaimana" tabindex="-1">Hubungannya dengan SemVer bagaimana? <a class="header-anchor" href="#hubungannya-dengan-semver-bagaimana" aria-label="Permalink to “Hubungannya dengan SemVer bagaimana?”">​</a></h3><ul><li><code>fix</code> -&gt; <code>PATCH</code></li><li><code>feat</code> -&gt; <code>MINOR</code></li><li>commit dengan <code>BREAKING CHANGE</code> (type apa pun) -&gt; <code>MAJOR</code></li></ul><h3 id="bagaimana-memversioning-ekstensi-spesifikasi-conventional-commits" tabindex="-1">Bagaimana memversioning ekstensi spesifikasi Conventional Commits? <a class="header-anchor" href="#bagaimana-memversioning-ekstensi-spesifikasi-conventional-commits" aria-label="Permalink to “Bagaimana memversioning ekstensi spesifikasi Conventional Commits?”">​</a></h3><p>Disarankan gunakan SemVer juga.</p><h3 id="bagaimana-jika-terlanjur-salah-memilih-type-commit" tabindex="-1">Bagaimana jika terlanjur salah memilih type commit? <a class="header-anchor" href="#bagaimana-jika-terlanjur-salah-memilih-type-commit" aria-label="Permalink to “Bagaimana jika terlanjur salah memilih type commit?”">​</a></h3><ul><li>Jika type masih valid tapi kurang tepat (mis. <code>fix</code> padahal <code>feat</code>), perbaiki riwayat sebelum merge/rilis (mis. via <code>git rebase -i</code>).</li><li>Jika type tidak valid (mis. <code>feet</code>), commit tetap tidak merusak repo, tetapi kemungkinan tidak terbaca oleh tooling berbasis spesifikasi.</li></ul><h3 id="apakah-semua-kontributor-wajib-mengikuti-spesifikasi-ini" tabindex="-1">Apakah semua kontributor wajib mengikuti spesifikasi ini? <a class="header-anchor" href="#apakah-semua-kontributor-wajib-mengikuti-spesifikasi-ini" aria-label="Permalink to “Apakah semua kontributor wajib mengikuti spesifikasi ini?”">​</a></h3><p>Tidak wajib. Pada workflow squash merge, maintainer bisa merapikan pesan commit saat penggabungan.</p><h3 id="bagaimana-conventional-commits-menangani-revert" tabindex="-1">Bagaimana Conventional Commits menangani revert? <a class="header-anchor" href="#bagaimana-conventional-commits-menangani-revert" aria-label="Permalink to “Bagaimana Conventional Commits menangani revert?”">​</a></h3><p>Spesifikasi tidak menetapkan aturan revert secara ketat. Tooling bisa memanfaatkan type dan footer untuk logika masing-masing.</p><p>Rekomendasi umum:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>revert: batalkan perubahan pada modul pembayaran</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Refs: 676104e, a215868</span></span></code></pre></div>`,54)])])}const h=e(t,[["render",o]]);export{k as __pageData,h as default};
